import{St as e,at as t,it as n,n as r,st as i,vt as a}from"./chunks/framework.D9OOHiq-.js";var o=JSON.parse(`{"title":"段 ID 表","description":"","frontmatter":{},"headers":[],"relativePath":"modules/corelib/stage-ids.md","filePath":"modules/corelib/stage-ids.md","lastUpdated":0}`),s={name:`modules/corelib/stage-ids.md`};function c(r,o,s,c,l,u){let d=e(`StageIdsTable`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="段-id-表" tabindex="-1">段 ID 表 <a class="header-anchor" href="#段-id-表" aria-label="Permalink to “段 ID 表”">​</a></h1><p>动作管道里全部段的 ID 与用途如下, 按名字就能定位</p><p>动作管道共有 <strong>218</strong> 个段, 分三类: source (目标源)<strong>29</strong> 个, gate (筛选/控制类段)<strong>17</strong> 个, action (动作)<strong>172</strong> 个. 其中 <strong>131</strong> 个是 CoreLib 内置段 (source 25 / gate 16 / action 90), 另外 <strong>87</strong> 个由本仓库的附属插件注册进同一套注册表: EmakiAttribute, EmakiCodex, EmakiCooking, EmakiForge, EmakiGem, EmakiItem, EmakiLevel, EmakiMobs, EmakiSkills, EmakiStrengthen, EmakiStorage</p><p>每行末尾的<strong>来源</strong>列写明这个段是谁注册的. 来源是 <code>CoreLib</code> 的是内置段, 点它的 ID 跳到<a href="./actions.html">动作系统</a> 对应段的详情节, 那里给出该段的<strong>全部专属参数</strong> (参数名, 数据类型, 取值范围, 默认值, 作用说明); 来源是插件名的是该插件注册的段, 点它的 ID 跳到那个插件自己的 CoreLib 动作页, 它的参数, 上下文变量与执行时机以那一页为准. EmakiMobs 暂时没有单独的动作页, 它的 8 个段只列 ID 与用途. 三类段通用的控制项与书写规范见动作系统的<a href="./actions.html#公共参数-所有段通用">公共参数 (所有段通用) </a></p><p>怎么用: 先点下方按钮按分类筛选, 再用输入框按<strong>段 ID, 用途文字与来源插件</strong>实时检索 (支持任意片段匹配, 中英文皆可, 如输入 <code>teleport</code>, <code>玩家</code> 或 <code>EmakiLevel</code>). 列表在页面加载时即完整输出, 不依赖脚本执行</p>`,5),i(d)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};